import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor cute_layernorm_forward(torch::Tensor x,
                                      torch::Tensor weight,
                                      torch::Tensor bias,
                                      double eps);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
#include <algorithm>

using namespace cute;

// -----------------------------------------------------------------------
// Kernel A: partial reduction of sum(x) and sum(x^2) per batch row (b),
// accumulated with atomicAdd into double buffers, one entry per batch.
// -----------------------------------------------------------------------
__global__ void ln_reduce_kernel(const float* __restrict__ X,
                                  double* __restrict__ sum_buf,
                                  double* __restrict__ sumsq_buf,
                                  int B, int N)
{
    int b = blockIdx.y;
    if (b >= B) return;
    const float* row = X + (int64_t)b * N;
    int N4 = N / 4;
    const float4* row4 = reinterpret_cast<const float4*>(row);
    int idx    = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;
    double s = 0.0, sq = 0.0;
    for (int i = idx; i < N4; i += stride) {
        float4 v4 = row4[i];
        s  += (double)v4.x + (double)v4.y + (double)v4.z + (double)v4.w;
        sq += (double)v4.x * (double)v4.x + (double)v4.y * (double)v4.y +
              (double)v4.z * (double)v4.z + (double)v4.w * (double)v4.w;
    }
    int tail_start = N4 * 4;
    for (int i = tail_start + idx; i < N; i += stride) {
        float v = row[i];
        s  += (double)v;
        sq += (double)v * (double)v;
    }
    unsigned mask = 0xffffffffu;
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
        s  += __shfl_down_sync(mask, s, offset);
        sq += __shfl_down_sync(mask, sq, offset);
    }
    __shared__ double shs[32];
    __shared__ double shsq[32];
    int lane = threadIdx.x & 31;
    int wid  = threadIdx.x >> 5;
    if (lane == 0) { shs[wid] = s; shsq[wid] = sq; }
    __syncthreads();
    int numWarps = blockDim.x / 32;
    if (wid == 0) {
        s  = (lane < numWarps) ? shs[lane]  : 0.0;
        sq = (lane < numWarps) ? shsq[lane] : 0.0;
        #pragma unroll
        for (int offset = 16; offset > 0; offset >>= 1) {
            s  += __shfl_down_sync(mask, s, offset);
            sq += __shfl_down_sync(mask, sq, offset);
        }
        if (lane == 0) {
            atomicAdd(&sum_buf[b], s);
            atomicAdd(&sumsq_buf[b], sq);
        }
    }
}

// -----------------------------------------------------------------------
// Kernel B: finalize mean / invstd per batch row.
// -----------------------------------------------------------------------
__global__ void ln_finalize_kernel(const double* __restrict__ sum_buf,
                                    const double* __restrict__ sumsq_buf,
                                    float* __restrict__ mean_buf,
                                    float* __restrict__ invstd_buf,
                                    int B, int N, float eps)
{
    int b = blockIdx.x * blockDim.x + threadIdx.x;
    if (b < B) {
        double m   = sum_buf[b] / (double)N;
        double var = sumsq_buf[b] / (double)N - m * m;
        if (var < 0.0) var = 0.0;
        mean_buf[b]   = (float)m;
        invstd_buf[b] = (float)(1.0 / sqrt(var + (double)eps));
    }
}

// -----------------------------------------------------------------------
// Kernel C: normalize + affine (elementwise gamma/beta over normalized_shape)
// -----------------------------------------------------------------------
__global__ void ln_norm_kernel(const float* __restrict__ X,
                                const float* __restrict__ W,
                                const float* __restrict__ Bs,
                                float* __restrict__ Y,
                                const float* __restrict__ mean_buf,
                                const float* __restrict__ invstd_buf,
                                int B, int N)
{
    int b = blockIdx.y;
    if (b >= B) return;
    const float* row_x = X + (int64_t)b * N;
    float* row_y = Y + (int64_t)b * N;
    int N4 = N / 4;
    const float4* row_x4 = reinterpret_cast<const float4*>(row_x);
    const float4* row_w4 = reinterpret_cast<const float4*>(W);
    const float4* row_b4 = reinterpret_cast<const float4*>(Bs);
    float4* row_y4 = reinterpret_cast<float4*>(row_y);
    float m  = mean_buf[b];
    float is = invstd_buf[b];
    int idx    = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;
    for (int i = idx; i < N4; i += stride) {
        float4 v = row_x4[i];
        float4 w = row_w4[i];
        float4 bb = row_b4[i];
        float4 out;
        out.x = (v.x - m) * is * w.x + bb.x;
        out.y = (v.y - m) * is * w.y + bb.y;
        out.z = (v.z - m) * is * w.z + bb.z;
        out.w = (v.w - m) * is * w.w + bb.w;
        row_y4[i] = out;
    }
    int tail_start = N4 * 4;
    for (int i = tail_start + idx; i < N; i += stride) {
        float v  = row_x[i];
        float w  = W[i];
        float bb = Bs[i];
        row_y[i] = (v - m) * is * w + bb;
    }
}

torch::Tensor cute_layernorm_forward(torch::Tensor x,
                                      torch::Tensor weight,
                                      torch::Tensor bias,
                                      double eps)
{
    TORCH_CHECK(x.is_cuda(), "x must be CUDA");
    TORCH_CHECK(weight.is_cuda() && bias.is_cuda(), "weight/bias must be CUDA");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
    TORCH_CHECK(weight.scalar_type() == at::kFloat, "weight must be float32");
    TORCH_CHECK(bias.scalar_type() == at::kFloat, "bias must be float32");

    auto x_c = x.contiguous();
    auto w_c = weight.contiguous();
    auto b_c = bias.contiguous();

    int64_t B = x_c.size(0);
    int64_t N = x_c.numel() / B;
    TORCH_CHECK(w_c.numel() == N, "weight numel mismatch");
    TORCH_CHECK(b_c.numel() == N, "bias numel mismatch");

    auto y = torch::empty_like(x_c);

    auto opts_d = x.options().dtype(at::kDouble);
    auto opts_f = x.options().dtype(at::kFloat);

    auto sum_buf    = torch::zeros({B}, opts_d);
    auto sumsq_buf  = torch::zeros({B}, opts_d);
    auto mean_buf   = torch::empty({B}, opts_f);
    auto invstd_buf = torch::empty({B}, opts_f);

    const int threads = 512;
    int blocks_a = (int)std::min<int64_t>(132, (N + threads - 1) / threads);
    if (blocks_a < 1) blocks_a = 1;
    int blocks_c = (int)std::min<int64_t>(1024, (N + threads - 1) / threads);
    if (blocks_c < 1) blocks_c = 1;
    dim3 gridA((unsigned)blocks_a, (unsigned)B);
    dim3 gridC((unsigned)blocks_c, (unsigned)B);

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    ln_reduce_kernel<<<gridA, threads, 0, stream>>>(
        x_c.data_ptr<float>(),
        sum_buf.data_ptr<double>(),
        sumsq_buf.data_ptr<double>(),
        (int)B, (int)N);

    int finalize_threads = 64;
    int finalize_blocks = (int)((B + finalize_threads - 1) / finalize_threads);
    ln_finalize_kernel<<<finalize_blocks, finalize_threads, 0, stream>>>(
        sum_buf.data_ptr<double>(),
        sumsq_buf.data_ptr<double>(),
        mean_buf.data_ptr<float>(),
        invstd_buf.data_ptr<float>(),
        (int)B, (int)N, (float)eps);

    ln_norm_kernel<<<gridC, threads, 0, stream>>>(
        x_c.data_ptr<float>(),
        w_c.data_ptr<float>(),
        b_c.data_ptr<float>(),
        y.data_ptr<float>(),
        mean_buf.data_ptr<float>(),
        invstd_buf.data_ptr<float>(),
        (int)B, (int)N);

    auto err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "layernorm kernel launch failed: ", cudaGetErrorString(err));

    return y;
}
"""

cute_layernorm_ext = load_inline(
    name="cute_layernorm_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["cute_layernorm_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    LayerNorm over `normalized_shape` implemented with a custom fused
    CUDA/CUTE kernel (mean/var reduction + affine normalization).
    """

    def __init__(self, normalized_shape: tuple):
        super(ModelNew, self).__init__()
        if isinstance(normalized_shape, int):
            normalized_shape = (normalized_shape,)
        self.normalized_shape = tuple(normalized_shape)
        self.eps = 1e-5

        self.weight = nn.Parameter(torch.ones(*self.normalized_shape))
        self.bias = nn.Parameter(torch.zeros(*self.normalized_shape))

        self._ext = cute_layernorm_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_layernorm_forward(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias.contiguous(),
            float(self.eps),
        )

